/* English build of palette.js — generated by cli/i18n.php, do not edit */
/* ==========================================================================
   panel Commands (Ctrl K): Pages from Sidebar (فهي بصلاحيات Employee أصلاً), Actions السريعة Allowed,
   Recently opened, والبحث Neighborhood in subscribers and Cards وMikroTik devices and Sites. تُحمَّل عند أول Open only.
   ========================================================================== */
(function (window, document) {
  'use strict';

  var SN = window.SN;
  var dlg, input, list, cfg;
  var pages = [], actions = null, remote = [], remoteQ = null, items = [], active = 0;
  var timer = null, ctrl = null, pending = '', lastHtml = null;
  var base = (document.querySelector('meta[name="base-url"]') || {}).content || '';
  var RECENT = 'sn-cmdk-recent:' + base;

  function esc(s) { return SN.esc(s); }
  function icon(n) { return SN.icon(n); }

  // توحيد الكتابة العربية (الهمزات, التاء المربوطة, الألف المقصورة, التشكيل والتطويل, Numbers)
  function norm(s) {
    return String(s || '').toLowerCase()
      .replace(/[ً-ٰٟـ]/g, '')
      .replace(/[أإآٱ]/g, 'ا').replace(/ة/g, 'ه').replace(/[ىئی]/g, 'ي').replace(/ؤ/g, 'و').replace(/ک/g, 'ك')
      .replace(/[٠-٩]/g, function (d) { return String(d.charCodeAt(0) - 1632); })
      .replace(/[۰-۹]/g, function (d) { return String(d.charCodeAt(0) - 1776); })
      .replace(/\s+/g, ' ').trim();
  }

  function collectPages() {
    var seen = {};
    pages = [];
    Array.prototype.forEach.call(document.querySelectorAll('.sidebar .nav-link[href]'), function (a) {
      if (seen[a.href]) { return; }
      seen[a.href] = true;
      var title = ((a.querySelector('.nav-text') || a).textContent || '').trim();
      var g = a.closest('.nav-group');
      var group = g ? (g.getAttribute('data-nav-group') || '') : '';
      var use = a.querySelector('use');
      var ic = use ? String(use.getAttribute('href') || '').split('#i-')[1] : '';
      pages.push({ type: 'page', icon: ic || 'file', title: title, sub: group, url: a.href, n: norm(title + ' ' + group) });
    });
  }

  function themeAction() {
    var dark = document.documentElement.getAttribute('data-theme') === 'dark';
    return {
      type: 'action', icon: dark ? 'sun' : 'moon', title: dark ? 'Light mode' : 'Dark mode', sub: '',
      run: function () { var b = document.querySelector('[data-theme-set="' + (dark ? 'light' : 'dark') + '"]'); if (b) { b.click(); } }
    };
  }

  function recent() {
    try { var r = JSON.parse(localStorage.getItem(RECENT) || '[]'); return Array.isArray(r) ? r : []; } catch (e) { return []; }
  }
  function remember(it) {
    if (!it.url || it.type === 'all') { return; }
    var r = recent().filter(function (x) { return x.url !== it.url; });
    r.unshift({ type: it.type, icon: it.icon, title: it.title, sub: it.sub || '', url: it.url });
    try { localStorage.setItem(RECENT, JSON.stringify(r.slice(0, 6))); } catch (e) { /* Storage Unavailable */ }
  }

  // صيغ الكلمة: بلا “ال” وبلا لاحقة الجمع or التاء المربوطة (“subscribers” تجد “Subscribers”)
  function forms(w) {
    var s = w;
    if (s.indexOf('ال') === 0 && s.length > 4) { s = s.slice(2); }
    if (/(ين|ون|ات)$/.test(s) && s.length > 4) { s = s.slice(0, -2); }
    else if (/ه$/.test(s) && s.length > 3) { s = s.slice(0, -1); }
    return s === w ? [w] : [w, s];
  }
  function match(it, words) {
    var hay = it.n || (it.n = norm(it.title + ' ' + (it.sub || '')));
    return words.every(function (w) { return forms(w).some(function (f) { return hay.indexOf(f) !== -1; }); });
  }

  function section(title, arr) {
    return arr.length ? [{ head: title }].concat(arr) : [];
  }

  function build() {
    var q = input.value.trim(), nq = norm(q), words = nq ? nq.split(' ') : [];
    var acts = (actions || []).concat([themeAction()]);
    var out = [];
    if (!words.length) {
      out = out.concat(section('Recently opened', recent()), section('Actions', acts));
    } else {
      out = out.concat(
        section('Pages', pages.filter(function (p) { return match(p, words); }).slice(0, 8)),
        section('Actions', acts.filter(function (a) { return match(a, words); })),
        section('Results', remoteQ === q ? remote : [])
      );
      if (cfg.search) {
        out.push({ type: 'all', icon: 'search', title: 'All results', sub: q, url: cfg.search + '?q=' + encodeURIComponent(q) });
      }
    }
    return out;
  }

  function render() {
    items = build();
    var html = '', n = 0;
    var selectable = items.filter(function (it) { return !it.head; });
    if (active >= selectable.length) { active = Math.max(0, selectable.length - 1); }
    items.forEach(function (it) {
      if (it.head) { html += '<div class="cmdk-group" role="presentation">' + esc(it.head) + '</div>'; return; }
      var i = n++;
      html += '<div class="cmdk-item' + (i === active ? ' is-active' : '') + '" role="option" id="cmdk-o' + i + '" data-i="' + i + '" aria-selected="' + (i === active) + '">' +
        '<span class="cmdk-ic">' + icon(it.icon || 'file') + '</span>' +
        '<span class="cmdk-txt"><span class="cmdk-title">' + esc(it.title) + '</span>' + (it.sub ? '<span class="cmdk-sub">' + String(it.sub).split(' · ').map(function (x) { return '<bdi>' + esc(x) + '</bdi>'; }).join(' · ') + '</span>' : '') + '</span></div>';
    });
    var q = input.value.trim();
    if (q && !selectable.some(function (it) { return it.type !== 'all'; }) && !pending) {
      html = '<div class="cmdk-empty">No results</div>' + html;
    }
    // لا Redo بناء إن لم تتغير Menu (الكتابة السريعة ترسم Less)
    if (html !== lastHtml) { list.innerHTML = html; lastHtml = html; }
    dlg.classList.toggle('is-loading', !!pending);
    input.setAttribute('aria-activedescendant', selectable.length ? 'cmdk-o' + active : '');
  }

  function selectable() { return items.filter(function (it) { return !it.head; }); }

  function move(d) {
    var s = selectable();
    if (!s.length) { return; }
    active = (active + d + s.length) % s.length;
    Array.prototype.forEach.call(list.querySelectorAll('.cmdk-item'), function (el) {
      var on = +el.getAttribute('data-i') === active;
      el.classList.toggle('is-active', on);
      el.setAttribute('aria-selected', on ? 'true' : 'false');
      if (on) { el.scrollIntoView({ block: 'nearest' }); }
    });
    input.setAttribute('aria-activedescendant', 'cmdk-o' + active);
  }

  function go(it, newTab) {
    if (!it) { return; }
    remember(it);
    if (it.run) { dlg.close(); it.run(); return; }
    if (newTab) { window.open(it.url, '_blank', 'noopener'); return; }
    dlg.close();
    window.location.href = it.url;
  }

  function fetchRemote(q, withActions) {
    if (!cfg.search) { return; }
    if (ctrl) { ctrl.abort(); }
    ctrl = window.AbortController ? new AbortController() : null;
    pending = q;
    render();
    fetch(cfg.search + '?q=' + encodeURIComponent(q) + (withActions ? '&actions=1' : ''), {
      headers: { 'Accept': 'application/json', 'X-Requested-With': 'XMLHttpRequest' }, credentials: 'same-origin', signal: ctrl ? ctrl.signal : undefined
    })
      .then(function (r) { return r.ok ? r.json() : null; })
      .then(function (d) {
        if (!d) { return; }
        if (d.actions) { actions = d.actions; }
        remote = d.items || [];
        remoteQ = q;
      })
      .catch(function () { /* بلا Call or طلب أحدث ألغاه: Results المحلية تبقى */ })
      .then(function () {
        if (pending === q) { pending = ''; }
        if (input.value.trim() === q || !q) { render(); }
      });
  }

  function onInput() {
    active = 0;
    var q = input.value.trim();
    clearTimeout(timer);
    if (cfg.search && q.length >= 2 && q !== remoteQ) {
      pending = q;
      timer = setTimeout(function () { fetchRemote(q, actions === null); }, 160);
    } else {
      pending = '';
    }
    render();
  }

  function init(el, options) {
    dlg = el;
    cfg = options || {};
    input = dlg.querySelector('.cmdk-input');
    list = dlg.querySelector('.cmdk-list');
    collectPages();
    input.addEventListener('input', onInput);
    input.addEventListener('keydown', function (e) {
      if (e.key === 'ArrowDown') { e.preventDefault(); move(1); }
      else if (e.key === 'ArrowUp') { e.preventDefault(); move(-1); }
      else if (e.key === 'Enter') { e.preventDefault(); go(selectable()[active], e.ctrlKey || e.metaKey); }
    });
    list.addEventListener('mousemove', function (e) {
      var row = e.target.closest('.cmdk-item');
      if (row && +row.getAttribute('data-i') !== active) { move(+row.getAttribute('data-i') - active); }
    });
    list.addEventListener('click', function (e) {
      var row = e.target.closest('.cmdk-item');
      if (row) { go(selectable()[+row.getAttribute('data-i')], e.ctrlKey || e.metaKey); }
    });
    if (cfg.search) { fetchRemote('', true); }
    refresh();
  }

  function refresh() {
    if (!dlg) { return; }
    active = 0;
    onInput();
  }

  window.SNPalette = { init: init, refresh: refresh, norm: norm };
})(window, document);
